CREATE COLUMN TABLE "TEST_AP"."OBSI" ("IndexType" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(30) NOT NULL , "Descr" NCLOB MEMORY THRESHOLD 1000, "UserSign" SMALLINT CS_INT, "ID" INTEGER CS_INT NOT NULL , "ValidFrom" LONGDATE CS_LONGDATE, "ValidTo" LONGDATE CS_LONGDATE, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBSI_IND_CODE_K" ON "TEST_AP"."OBSI" ( "IndexType" ASC, "Code" ASC )